    /**
     * Resets all references to other model objects or collections of model objects.
     *
     * This method is a user-space workaround for PHP's inability to garbage collect
     * objects with circular references (even in PHP 5.3). This is currently necessary
     * when using Propel in certain daemon or large-volume/high-memory operations.
     *
     * @param boolean $deep Whether to also clear the references on all referrer objects.
     */
    public function clearAllReferences($deep = false)
    {
        if ($deep && !$this->alreadyInClearAllReferencesDeep) {
            $this->alreadyInClearAllReferencesDeep = true;
            if ($this->collComrecibidaInteresadoss) {
                foreach ($this->collComrecibidaInteresadoss as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collUnidaddocumentalInteresadoss) {
                foreach ($this->collUnidaddocumentalInteresadoss as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collReprlegalInteresados) {
                foreach ($this->collReprlegalInteresados as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collServicioInteresadoss) {
                foreach ($this->collServicioInteresadoss as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collEnviadaInteresadoss) {
                foreach ($this->collEnviadaInteresadoss as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->aCiudad instanceof Persistent) {
              $this->aCiudad->clearAllReferences($deep);
            }
            if ($this->aTipoIdentificacion instanceof Persistent) {
              $this->aTipoIdentificacion->clearAllReferences($deep);
            }
            if ($this->aTipoGenero instanceof Persistent) {
              $this->aTipoGenero->clearAllReferences($deep);
            }
            if ($this->aUsuario instanceof Persistent) {
              $this->aUsuario->clearAllReferences($deep);
            }

            $this->alreadyInClearAllReferencesDeep = false;
        } // if ($deep)

        if ($this->collComrecibidaInteresadoss instanceof PropelCollection) {
            $this->collComrecibidaInteresadoss->clearIterator();
        }
        $this->collComrecibidaInteresadoss = null;
        if ($this->collUnidaddocumentalInteresadoss instanceof PropelCollection) {
            $this->collUnidaddocumentalInteresadoss->clearIterator();
        }
        $this->collUnidaddocumentalInteresadoss = null;
        if ($this->collReprlegalInteresados instanceof PropelCollection) {
            $this->collReprlegalInteresados->clearIterator();
        }
        $this->collReprlegalInteresados = null;
        if ($this->collServicioInteresadoss instanceof PropelCollection) {
            $this->collServicioInteresadoss->clearIterator();
        }
        $this->collServicioInteresadoss = null;
        if ($this->collEnviadaInteresadoss instanceof PropelCollection) {
            $this->collEnviadaInteresadoss->clearIterator();
        }
        $this->collEnviadaInteresadoss = null;
        $this->aCiudad = null;
        $this->aTipoIdentificacion = null;
        $this->aTipoGenero = null;
        $this->aUsuario = null;
